def work_on_strings(a, b):
    def swap_case(s1, s2):
        result = []
        for char in s1:
            swap_count = sum(1 for c in s2 if c.lower() == char.lower())
            if swap_count % 2 == 1:
                char = char.swapcase()
            result.append(char)
        return ''.join(result)

    return swap_case(a, b) + swap_case(b, a)
